import java.util.Arrays;

public final class UnionFind {
    private final int[] parent;
    private final int[] componentSizes;
    private int components;

    public UnionFind(int size) {
        validateSize(size);
        parent = new int[size];
        componentSizes = new int[size];
        components = size;

        initializeComponents();
    }

    private static void validateSize(int size) {
        if (size < 0) {
            throw new IllegalArgumentException("size must be non-negative");
        }
    }

    private void initializeComponents() {
        for (int i = 0; i < parent.length; i++) {
            parent[i] = i;
            componentSizes[i] = 1;
        }
    }

    public int find(int element) {
        validateElement(element);
        return rootOf(element);
    }

    public boolean union(int first, int second) {
        int firstRoot = find(first);
        int secondRoot = find(second);

        if (firstRoot == secondRoot) {
            return false;
        }

        attachRoots(firstRoot, secondRoot);
        components--;
        return true;
    }

    public boolean connected(int first, int second) {
        return find(first) == find(second);
    }

    public int size() {
        return parent.length;
    }

    public int components() {
        return components;
    }

    public int componentSize(int element) {
        return componentSizes[find(element)];
    }

    @Override
    public String toString() {
        return "UnionFind{parent=" + Arrays.toString(parent)
                + ", componentSizes=" + Arrays.toString(componentSizes)
                + ", components=" + components
                + '}';
    }

    private int rootOf(int element) {
        int root = element;

        while (root != parent[root]) {
            root = parent[root];
        }

        while (element != root) {
            int next = parent[element];
            parent[element] = root;
            element = next;
        }

        return root;
    }

    private void attachRoots(int firstRoot, int secondRoot) {
        if (componentSizes[firstRoot] < componentSizes[secondRoot]) {
            int smallerRoot = firstRoot;
            firstRoot = secondRoot;
            secondRoot = smallerRoot;
        }

        parent[secondRoot] = firstRoot;
        componentSizes[firstRoot] += componentSizes[secondRoot];
    }

    private void validateElement(int element) {
        if (element < 0 || element >= parent.length) {
            throw new IndexOutOfBoundsException(invalidElementMessage(element));
        }
    }

    private String invalidElementMessage(int element) {
        if (parent.length == 0) {
            return "element is out of bounds for an empty UnionFind: " + element;
        }

        return "element must be between 0 and " + (parent.length - 1) + ": " + element;
    }
}

public final class UnionFindTest {
    private static int testsRun;

    private UnionFindTest() {
    }

    public static void main(String[] args) {
        runTest("new elements start disconnected", UnionFindTest::testNewElementsStartDisconnected);
        runTest("union connects elements", UnionFindTest::testUnionConnectsElements);
        runTest("union reports merge status", UnionFindTest::testUnionReturnsWhetherMergeHappened);
        runTest("component count tracks merges", UnionFindTest::testComponentCountTracksMerges);
        runTest("component size tracks merges", UnionFindTest::testComponentSizeTracksMerges);
        runTest("invalid elements are rejected", UnionFindTest::testInvalidElementsAreRejected);

        System.out.println("All " + testsRun + " UnionFind tests passed.");
    }

    private static void testNewElementsStartDisconnected() {
        UnionFind unionFind = new UnionFind(3);

        assertFalse(unionFind.connected(0, 1), "new elements should start disconnected");
    }

    private static void testUnionConnectsElements() {
        UnionFind unionFind = new UnionFind(4);

        unionFind.union(0, 1);
        unionFind.union(2, 3);
        unionFind.union(1, 3);

        assertTrue(unionFind.connected(0, 3), "transitive unions should connect elements");
    }

    private static void testUnionReturnsWhetherMergeHappened() {
        UnionFind unionFind = new UnionFind(2);

        assertTrue(unionFind.union(0, 1), "first union should merge sets");
        assertFalse(unionFind.union(0, 1), "repeated union should not merge sets");
    }

    private static void testComponentCountTracksMerges() {
        UnionFind unionFind = new UnionFind(4);

        assertEquals(4, unionFind.components(), "initial component count");
        unionFind.union(0, 1);
        unionFind.union(2, 3);
        unionFind.union(1, 3);

        assertEquals(1, unionFind.components(), "component count after merges");
    }

    private static void testComponentSizeTracksMerges() {
        UnionFind unionFind = new UnionFind(5);

        assertEquals(1, unionFind.componentSize(0), "initial component size");
        unionFind.union(0, 1);
        unionFind.union(2, 3);

        assertEquals(2, unionFind.componentSize(0), "component size after first merge");
        assertEquals(2, unionFind.componentSize(3), "component size after second merge");

        unionFind.union(1, 2);

        assertEquals(4, unionFind.componentSize(0), "component size after joining components");
        assertEquals(1, unionFind.componentSize(4), "unmerged element size");
    }

    private static void testInvalidElementsAreRejected() {
        UnionFind unionFind = new UnionFind(1);
        UnionFind emptyUnionFind = new UnionFind(0);

        assertThrows(
                IndexOutOfBoundsException.class,
                () -> unionFind.find(-1),
                "negative element should be rejected"
        );
        assertThrows(
                IndexOutOfBoundsException.class,
                () -> unionFind.find(1),
                "element beyond size should be rejected"
        );
        assertThrows(
                IndexOutOfBoundsException.class,
                () -> emptyUnionFind.find(0),
                "empty union-find should reject every element"
        );
        assertThrows(
                IllegalArgumentException.class,
                () -> new UnionFind(-1),
                "negative size should be rejected"
        );
    }

    private static void assertTrue(boolean condition, String message) {
        if (!condition) {
            throw new AssertionError(message);
        }
    }

    private static void runTest(String name, Runnable test) {
        try {
            test.run();
            testsRun++;
        } catch (AssertionError error) {
            throw new AssertionError(name + " failed: " + error.getMessage(), error);
        }
    }

    private static void assertFalse(boolean condition, String message) {
        assertTrue(!condition, message);
    }

    private static void assertEquals(int expected, int actual, String message) {
        if (expected != actual) {
            throw new AssertionError(message + ": expected " + expected + ", got " + actual);
        }
    }

    private static void assertThrows(
            Class<? extends RuntimeException> expectedType,
            Runnable action,
            String message
    ) {
        try {
            action.run();
        } catch (RuntimeException exception) {
            if (!expectedType.isInstance(exception)) {
                throw new AssertionError(
                        message + ": expected " + expectedType.getSimpleName()
                                + ", got " + exception.getClass().getSimpleName()
                );
            }

            return;
        }

        throw new AssertionError(message + ": expected " + expectedType.getSimpleName());
    }
}

public final class UnionFindDemo {
    private UnionFindDemo() {
    }

    public static void main(String[] args) {
        UnionFind unionFind = new UnionFind(5);
        unionFind.union(1, 2);
        unionFind.union(3, 4);

        System.out.println("Are 1 and 2 in the same set? " + unionFind.connected(1, 2));
    }
}
